def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(3 * h):
        rr = r % h
        if r < h:
            rr = h - 1 - rr
        for_row = []
        for c in range(3 * w):
            cc = c % w
            if c < w:
                cc = w - 1 - cc
            for_row.append(grid[rr][cc])
        out.append(for_row)
    return out
