def transform(grid):
    n = len(grid)
    m = len(grid[0])

    def source_index(i, size):
        block, offset = divmod(i, size)
        return size - 1 - offset if block % 2 == 0 else offset

    return [
        [
            grid[source_index(r, n)][source_index(c, m)]
            for c in range(3 * m)
        ]
        for r in range(3 * n)
    ]
